// Keeps everything that is not this site's own code (Pyodide and its packages from the CDN, and the
// wheels the build vendors under vendor/) in
// Cache Storage for 30 days, so a return visit starts without downloading ~50 MB again. The
// site's own files always come from the network, so a deploy is picked up on the next load.
const CACHE = "third-party-v1";
const MAX_AGE_MS = 30 * 24 * 3600 * 1000;
const STAMP = "x-nor-cached-at";

