attachment.snippet:
1	// Keeps everything that is not this site's own code (Pyodide and its packages from the CDN, and the
2	// wheels the build vendors under vendor/) in
3	// Cache Storage for 30 days, so a return visit starts without downloading ~50 MB again. The
4	// site's own files always come from the network, so a deploy is picked up on the next load.
5	const CACHE = "third-party-v1";
6	const MAX_AGE_MS = 30 * 24 * 3600 * 1000;
7	const STAMP = "x-nor-cached-at";
8	
9	self.addEventListener("install", () => self.skipWaiting());
10	self.addEventListener("activate", (e) => e.waitUntil(self.clients.claim()));
11	
12	self.addEventListener("fetch", (e) => {
13	  const req = e.request;
14	  const u = new URL(req.url);
15	  const own = u.origin === self.location.origin && !u.pathname.includes("/vendor/");
16	  if (req.method !== "GET" || own) return;
17	  e.respondWith(cached(req));
18	});
19	
20	async function cached(req) {
21	  const cache = await caches.open(CACHE);
22	  const hit = await cache.match(req.url);
23	  const at = hit && Number(hit.headers.get(STAMP));
24	  if (hit && at && Date.now() - at < MAX_AGE_MS) return hit;

