    sel.innerHTML = Object.entries(m.finders).map(([k, v]) => `<option value="${k}">${v}</option>`).join("");
    sel.disabled = false; busy(false);
    status(`Ready (${m.secs.toFixed(0)} s to load). Open an image.`);
