    st.H = m.H; st.W = m.W; st.um = m.um; const n = m.H * m.W;
    st.img = { r: m.images.subarray(0, n), g: m.images.subarray(n, 2 * n), b: m.images.subarray(2 * n, 3 * n), mask: m.images.subarray(3 * n, 4 * n) };
