  const ctx = c.getContext("2d"), im = ctx.createImageData(st.W, st.H), d = im.data;
  const dapi = $("#show-dapi").checked, mask = $("#show-mask").checked, { r, g, b } = st.img, mk = st.img.mask;
  for (let i = 0, j = 0; i < r.length; i++, j += 4) {
