content.content:
:root {
  --bg: #16181c; --panel: #1f2227; --line: #33373e; --text: #e6e6e6; --dim: #9aa0a8;
  --pink: rgb(255, 105, 200); --blue: rgb(0, 140, 255); --accent: #4c8dff;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--text); font: 14px/1.4 system-ui, sans-serif; }
header { display: flex; gap: 16px; align-items: center; flex-wrap: wrap; padding: 10px 16px; border-bottom: 1px solid var(--line); }
h1 { font-size: 18px; margin: 0; }
h2 { font-size: 15px; margin: 0; }
button, select, input { font: inherit; color: var(--text); background: var(--panel); border: 1px solid var(--line); border-radius: 4px; }
button { padding: 3px 10px; cursor: pointer; }
button:disabled { opacity: .45; cursor: default; }
button.primary { background: var(--accent); border-color: var(--accent); margin-top: 8px; }
label.file { background: var(--accent); padding: 4px 12px; border-radius: 4px; cursor: pointer; }
label.file input { display: none; }
#status { color: var(--dim); }
#status.err { color: #ff7b7b; }

main { display: flex; height: calc(100vh - 52px); min-height: 480px; }
aside { width: 340px; flex: none; overflow-y: auto; border-right: 1px solid var(--line); padding: 10px 12px; }
aside section + section { margin-top: 18px; }
.sec-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.hint { color: var(--dim); font-size: 12px; margin: 4px 0 8px; }
.hint.slow { color: #ffc864; }

.filter { background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 6px 8px; margin-bottom: 6px; }
.filter.off { opacity: .5; }
.filter .top { display: flex; gap: 6px; align-items: baseline; }
.filter .letter { font-weight: 700; width: 14px; }
.filter .text { flex: 1; font-size: 13px; }
.filter .n { color: var(--dim); font-size: 12px; white-space: nowrap; }
.param { display: grid; grid-template-columns: 1fr 70px; gap: 2px 6px; align-items: center; margin-top: 4px; font-size: 12px; }
.param .name { grid-column: 1 / 3; color: var(--dim); }
.param input[type=range] { width: 100%; }
.param input[type=number] { width: 70px; padding: 1px 3px; }
.dparam { display: flex; justify-content: space-between; align-items: center; gap: 8px; font-size: 12px; margin: 3px 0; }
.dparam input[type=text], .dparam input[type=number] { width: 110px; padding: 1px 3px; }
.dparam.changed .name { color: #ffc864; }

#view { flex: 1; min-width: 0; display: flex; flex-direction: column; }
.toolbar { display: flex; gap: 12px; align-items: center; flex-wrap: wrap; padding: 6px 10px; border-bottom: 1px solid var(--line); font-size: 13px; }
#counts { margin-left: auto; color: var(--dim); }
#scroller { flex: 1; overflow: auto; position: relative; }
#empty { color: var(--dim); padding: 40px; text-align: center; }
#stage { position: relative; }
#base { image-rendering: pixelated; display: block; }
#overlay { position: absolute; left: 0; top: 0; }
#overlay path { fill: none; vector-effect: non-scaling-stroke; stroke-width: 1; stroke-opacity: .6; }
#overlay .red { stroke-opacity: .45; }
#overlay .pass path { stroke: var(--pink); }
#overlay .fail path { stroke: var(--blue); }
#overlay .hidden, #overlay.no-fails .fail, #overlay.no-labels text, #overlay.no-lines .lines { display: none; }
#overlay .lines { display: none; }
#overlay .pass .lines { display: inline; }
#overlay.no-lines .pass .lines { display: none; }
#overlay .lines line { stroke: #fff; vector-effect: non-scaling-stroke; stroke-width: 1; }
#overlay .lines line.r { stroke-width: 2; }
#overlay text { paint-order: stroke; stroke: #000; stroke-width: 2px; stroke-opacity: .6; font-family: system-ui, sans-serif; }
#overlay .hit { fill: transparent; cursor: pointer; }
#overlay .forced path { stroke-dasharray: 2 1; stroke-opacity: 1; }

#list-sec, #summary-sec { padding: 12px 16px; border-top: 1px solid var(--line); }
#list { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 8px; margin-top: 8px; }
.card { background: var(--panel); border: 1px solid var(--line); border-radius: 6px; padding: 6px; font-size: 12px; }
.card canvas { display: block; margin: 0 auto 4px; image-rendering: pixelated; cursor: pointer; }
.card .head { display: flex; justify-content: space-between; align-items: center; }
.card .num { color: var(--pink); font-weight: 700; }
.card .star { margin-left: auto; margin-right: 4px; color: #ffc864; }
.card.kept { border-color: #ffc864; }
.card.removed { opacity: .35; }
.card button { padding: 0 6px; font-size: 11px; }
.card table { width: 100%; border-collapse: collapse; }
.card td:last-child { text-align: right; font-variant-numeric: tabular-nums; }
.card td { color: var(--dim); } .card td:last-child { color: var(--text); }

#summary table { border-collapse: collapse; margin-top: 8px; font-variant-numeric: tabular-nums; }
#summary th, #summary td { padding: 4px 10px; text-align: right; border-bottom: 1px solid var(--line); }
#summary th:first-child, #summary td:first-child { text-align: left; }
#summary .hists { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 12px; }
#summary .hist { font-size: 12px; color: var(--dim); }
#summary .hist rect { fill: var(--pink); opacity: .75; }
#summary .reasons { margin-top: 12px; color: var(--dim); font-size: 13px; }

#tip { position: fixed; pointer-events: none; background: #000d; border: 1px solid var(--line); border-radius: 4px; padding: 6px 8px; font-size: 12px; max-width: 320px; z-index: 10; white-space: pre-line; }

@media (max-width: 800px) {
  main { flex-direction: column; height: auto; }
  aside { width: 100%; border-right: 0; border-bottom: 1px solid var(--line); }
  #view { height: 70vh; }
}

.spin { display: inline-block; width: 14px; height: 14px; border: 2px solid var(--line); border-top-color: var(--pink); border-radius: 50%; animation: spin .8s linear infinite; visibility: hidden; }
.spin.on { visibility: visible; }
.spin.big { width: 44px; height: 44px; border-width: 4px; visibility: visible; }
@keyframes spin { to { transform: rotate(360deg); } }
#view { position: relative; }
#busy { position: absolute; inset: 42px 0 0 0; z-index: 5; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; background: #16181cb0; color: var(--text); }
#busy[hidden] { display: none; }
#busy-time { color: var(--dim); font-variant-numeric: tabular-nums; }

