// polish <url> <tif> <outdir>: finds candidates, opens the Show menu, flips theme and view; screenshots each
import { chromium } from "playwright";
const [url, tif, out] = process.argv.slice(2);
const b = await chromium.launch({ executablePath: "/opt/pw-browsers/chromium", args: ["--ignore-certificate-errors-spki-list=KnP1OnzHv/y42eRQmbGwoYTHcSJF448m6CU5mdngwKk="] });
const p = await b.newPage({ viewport: { width: 1440, height: 850 }, colorScheme: "dark" });
p.on("pageerror", (e) => console.log("PAGEERROR", e.message));
await p.goto(url);
await p.waitForFunction(() => /Ready/.test(document.querySelector("#status").textContent), null, { timeout: 300000 });
await p.setInputFiles("#file", tif);
await p.waitForFunction(() => /Press Find/.test(document.querySelector("#status").textContent), null, { timeout: 300000 });
await p.click("#find");
await p.waitForFunction(() => /finalists/.test(document.querySelector("#sb-counts").textContent), null, { timeout: 300000 });
await p.waitForTimeout(500);
await p.click("#show-menu summary"); await p.waitForTimeout(200);
await p.screenshot({ path: out + "/polish_dark.png" });
await p.click("#show-lines"); 
console.log("lines hidden", await p.evaluate(() => document.querySelector("#overlay").classList.contains("no-lines")));
await p.mouse.click(700, 500); await p.waitForTimeout(200);
console.log("menu closed", await p.evaluate(() => !document.querySelector("#show-menu").open));
const g = await p.$("#overlay g.pass .hit"); await g.hover();
console.log("cursor", await p.evaluate(() => getComputedStyle(document.querySelector("#overlay g.pass .hit")).cursor));
await p.click("#theme"); await p.waitForTimeout(200);
console.log("switch", await p.textContent("#switch"));
await p.screenshot({ path: out + "/polish_light.png" });
await p.click("#switch"); console.log("switch", await p.textContent("#switch"));
await p.screenshot({ path: out + "/footer.png", clip: { x: 0, y: 850 - 60, width: 1440, height: 60 } });
await b.close();
EOF
